$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_307181015f28b24b5cf56a56f268fefc'] = 'Tämän vaihtoehdon avulla voit muuttaa tässä osiossa olevaan maahan liittyvää asiakasoletusryhmää, kun asiakas valitsee oletusosoitteen tai ostoprosessin aikana. Jos valitulla osoitteella ei ole voimassa olevaa ALV-numeroa, järjestelmä vaihtuu Prestashopin asiakasoletusryhmään';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f008d6b21c614caada820eac4e9ae732'] = 'Poista asiakas toisista ryhmistä';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_48cade9acdfa67cc5014f8e885463462'] = 'Tämä vaihtoehto poistaa asiakkaan ryhmistä, joihin se on aiemmin määritetty, ja jättää sen vain ryhmään, joka on määritetty tässä osiossa maittain. Oletusryhmä muutetaan nykyiseksi määrätyksi ryhmäksi.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ccca8b7e16706b70eb3862d8cac1cf3'] = 'Aktivointiasetukset';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5c421a5582c9affbd59ce0fbe57a4060'] = 'EU-maat on valittu oletuksena. [Countries for validation] -vaihtoehto on hyödyllinen vain sellaisten maiden lisäämiseen tai poistamiseen, jotka kuuluvat Euroopan unioniin tai joilla on sopimus yhteisön sisäisistä toiminnoista. Normaalitilanteessa tämä vaihtoehto on ennalta määritetty, eikä sitä pidä muuttaa. Ota huomioon, että Pohjois-Irlanti sisältyy yhteisön sisäisiin toimiin ja kuuluu Yhdistyneeseen kuningaskuntaan (Englanti).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1a7c23373b408af50cb839fbe7d52c85'] = 'Back-office validointi';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_882cb664782409edd93fd5d3ab85efec'] = 'Aktivoi ALV-numeroiden vahvistus Back-office-sovelluksen Osoite-osiossa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_50da52ae50ce1c69d9ec84f9ae7de0e1'] = 'Jotkut moduulit käyttävät taustatoimistoon kuuluvia ohjaimia asiakasosoitteiden luomiseen cron-tehtävien tai prosessien kautta. Tämä vaihtoehto on aktivoitava, jotta moduuli voi vahvistaa näiden luotujen osoitteiden ALV-numerot.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_bb7bd05d489b31a0c31edfd4897745f4'] = 'Etukonttorin vahvistus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9176ffc4cac7d0b19daba445c764c2b1'] = 'Aktivoi ALV-numeroiden vahvistus Front Officen Osoite-osiossa, kun asiakas luo tai muokkaa osoitetta tai kassaprosessin aikana.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_32b4427fd2b69a2c80d21c213e50f974'] = 'Vahvistettavat maat';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f173aae292b6e3a5365cb4ac449d60b5'] = 'Valitse maat, joissa validointi aktivoidaan. Sinun ei tule muuttaa tätä luetteloa, ellei yhteisön sisäisen toiminnan määräykset muutu ja asianomaisia maita muuteta.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2d59f051b72e3fab1863a7720267abf8'] = 'CTRL ja napsauta tai napsauta ja vedä useita vaihtoehtoja valitaksesi.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c9cc8cce247e49bae79f15173ce97354'] = 'Tallentaa';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b51d6159f43c28990c668ee0f5722e68'] = 'Ota huomioon, että jotta verovapautustoimenpide sujuisi juridisesti oikein, kauppiaan tulee asiakkaan lisäksi olla rekisteröitynä voimassa olevaan yhteisön sisäiseen arvonlisäverovelvolliseen. Järjestelmä vahvistaa VIES:n tai GOV.UK:n kautta kauppiaan yhteisön sisäisen ALV-numeron ennen sen tallentamista tietokantaan.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4c4974ffdbc418a104b9ac8fe50329f2'] = 'Kauppiaan ALV';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c5e748d9e2d43bffbcf34fba6bf83c8'] = 'Lisää kauppiaan ALV-numero (ISO-koodilla), jonka yritys on rekisteröity yhteisön sisäistä toimintaa varten. Kirjoita koko numero iso-koodilla (esim. FR17852960). Yhdistyneen kuningaskunnan ALV-numerot eivät ole sallittuja.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1709b640f134a404881e88edc01258bc'] = 'Tämä on tarpeen kaksisuuntaisen validointijärjestelmän valinnassa. Voidaan jättää tyhjäksi, jos et käytä kaksisuuntaista vahvistusjärjestelmää.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d927b3b03a13bf31b7eb8f6ff92e07ca'] = 'Näytä varoitusviesti osoitteessa';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8c0a80538a54ae2b99f5d930b34f65e2'] = 'Näyttää varoitusviestit asiakastilin osoiteosiossa, kun heillä ei ole rekisteröityä voimassa olevaa ALV-numeroa tai heillä on rekisteröitävä ALV-numero (pakollinen kenttävaihtoehto aktivoitu) tai yrityskenttä on vahvistettava (yrityksen vahvistusvaihtoehto aktivoitu).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6bf5595b28f11a3701d3dc6c9d6e449d'] = 'Toimii vain Prestashop 1.7:ssä tai uudemmissa';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e119406d93b7385c70d4b607a81bcf32'] = 'Älä salli kassaa, kun osoite on puutteellinen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a2f3bd6da6361f19d81c48c65446422f'] = 'Tämä vaihtoehto ei salli asiakkaan jatkaa ostoprosessia, jos valitussa osoitteessa on ALV-numero tai yrityksen nimikenttä, joka on vahvistettava tai täytettävä (Riippuen valituista vahvistus- ja ALV-kentän määritysvaihtoehdoista). Hyödyllinen vaihtoehto asiakkaille, joilla on jo rekisteröity osoite tietokantaan';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d2afdcacd59b06e5541e4c32b24581b7'] = 'Mukautettu hintalohko';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6607b1376017ff8c5845ae0e911f962b'] = 'Lisää mukautettu teksti tuotteen hintakenttään (hinnan alle), niin se näytetään, kun asiakas on valinnut osoitteen, jolla on voimassa oleva ALV-numero ja on verovapaa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1b94355921381017449e017baaa43e5e'] = 'On erittäin suositeltavaa käyttää kaksisuuntaista validointijärjestelmää verovapautuksen oikeudellisen eheyden varmistamiseksi yhteisön sisäisissä liiketoimissa, jolloin varmistetaan sekä kauppiaan että asiakkaan ALV-numero. Kaksisuuntaista vahvistusta varten on tarpeen määrittää kauppiaan alv-numero yleisissä asetuksissa. Jos Kauppiaan alv -vaihtoehto on tyhjä, järjestelmä käyttää joka tapauksessa yksisuuntaista vahvistusta.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8dd10878b69a18f881af0c0e36247cb0'] = 'Validointijärjestelmä';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_24b0f41249450fb2b8d43025022f44a8'] = 'Valitse ALV-numeron vahvistusjärjestelmä. Validation 1-way vain tarkistaa ja vahvistaa asiakkaan ALV-numeron, vaikka kauppiaalla ei olisi voimassa olevaa ALV-numeroa. Vahvistus 2-suuntainen lähettää kauppiaan ALV-numeron ja asiakkaan ALV-numeron ja tarkistaa, ovatko molemmat jo rekisteröityneet suorittamaan verovapaita toimintoja yhteisön sisällä.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c106d4c676d2f70ee14fe9ac8b53a99'] = 'Toimii vain [Format + API system] -vahvistusjärjestelmän valinnan kanssa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_147dc6e7f6af2b9b3bb0cf77bab90e41'] = 'Vahvistus yksisuuntaisesti';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4792ea7be8342c48e29cf2eeae895962'] = 'Vahvistus 2-suuntainen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_29dcf8f9e61af7c1f9e4bbd16cf4f2cf'] = 'Vahvistustila';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c5a4695fbfd74fcfac2a3d505c66d43b'] = 'Tämä vaihtoehto määrittää ALV-vahvistustavan. Tiukka tila vahvistaa ALV-numerot asiakkaan asettamassa oikeassa muodossa (esim. FR01609493). Älykäs tila vahvistaa ALV-numerot, vaikka asiakas ei olisi lisännyt muotoa oikein (esim. FR-01609493, FR 01609493, FR01.609.493) ja tallentaa kelvollisena muodossa (esim. FR01609493)';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_006576df800107db40832e2e0fd44931'] = 'Tiukka tila';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_dfea54ef85aa32f8489ae0f672d91c5a'] = 'Älykäs tila';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_94b93271d0dfce2b59ba77cc690415a3'] = 'Validointityyppi';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_99dd2d580dc5196d7e919645a054c28a'] = 'Tämä vaihtoehto määrittää ALV-vahvistuksen tyypin. Muodin vahvistustila vahvistaa vain ALV-numeromuodon (esim. FR01609493). Muoto + API-vahvistus vahvistaa ALV-numeromuodon ja vahvistaa sen VIES- tai GOV.UK-sovellusliittymäjärjestelmään (suositellaan ALV-vapautuksen vuoksi).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5718f767fd5edcc521f57c23f4527725'] = 'Muodin vahvistus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_3b19c288b70dc9b277b83cb937d1df74'] = 'Muoto + API -järjestelmän validointi';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_54df18253716c9795f66ed2d4255833b'] = 'Yrityksen validointi';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_93370977d5f528ed94a8f7cf6e7156be'] = 'Jos se on käytössä, yrityksen nimikenttä vahvistetaan yhdessä VIES/GOV.UK-järjestelmästä saatujen tietojen kanssa ALV-numerosta. Jos asiakas ei kirjoita yrityksen nimeä täsmälleen sellaisena kuin se näkyy VIES/GOV.UK-järjestelmän tietokannassa, osoitetta ei vahvisteta tällä ALV-numerolla. Aiemmat asiakkaat, jotka ovat rekisteröityneet tietokantaan yrityksen nimellä vielä vahvistamattomalla, mutta voimassa olevalla arvonlisäverovelvollisella, ovat velvollisia päivittämään osoitetiedot ennen ostoksen tekemistä kaupassa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ac50ccc149ebb161e8d8d19c3a6a946f'] = 'Virheiden välttämiseksi osoitelomakkeissa on varmistettava, että \"yritys\"-kenttä näkyy lomakkeessa. Jos tämä vaihtoehto on käytössä, tämä kenttä on osoitelomakkeen vaatima.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_71e56d83a626d8268caf28e8eac3d64a'] = 'Lisää yrityksen nimi automaattisesti';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_52800a2170bf04b8329ec097aa422d63'] = 'Jos tämä on käytössä, järjestelmä lisää VIES- tai GOV.UK-järjestelmästä otetun rekisteröidyn yrityksen nimen, kun asiakas rekisteröi osoitteen, jolla on voimassa oleva ALV-numero. Jos asiakas on syöttänyt yrityskenttään toisen yrityksen nimen, se korvataan oikealla järjestelmään rekisteröidyllä nimellä.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_be496e62d1ca3007170567553e8441c0'] = 'Tämä vaihtoehto ei ole yhteensopiva [Company validation] -asetuksen kanssa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_de333ce299100de1723bb0d246f8845e'] = 'Salli päällekkäinen ALV';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5c5c48e6b16c9c8e7d5f2924dba18076'] = 'Tämä vaihtoehto ottaa käyttöön tai poistaa käytöstä erilaisten asiakkaiden rekisteröinnit samoilla ALV-numeroilla.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_73e32e03f4ab7374222b68de7f97a2b6'] = 'Ohita API-järjestelmän epäonnistuminen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9f5f6676c393f344b028ba9c4e77159f'] = 'Tämä vaihtoehto ohittaa vahvistuksen, jos VIES/GOV.UK API -järjestelmä epäonnistuu vahvistusprosessin aikana. Asiakas voi jatkaa osoitteen rekisteröintiä ja kassalla. ALV-numero näkyy [Validated] ja järjestelmän tila punaisena muodossa [API request processing error] ALV-hallintaluettelossa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c65e5a2319190e3346c5ac53ad702b2b'] = 'Tämä vaihtoehto toimii vain API-järjestelmän validoinnissa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d337d426b6c49df575234f8e7a001736'] = 'Tallenna isoilla kirjaimilla';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ca36376b1a467f9f5c8f2fca7614721'] = 'Ota tämä vaihtoehto käyttöön tallentaaksesi ALV-numeron isoilla kirjaimilla, kun asiakas suorittaa lisäys- tai päivitystoiminnot osoitemuodossa. Esim: FR01609493 sen sijaan fr01609493';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_85fffe8f5074d606fa202fa5ae90d8bb'] = 'Musta lista';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a9fc6209ac169e499232af8c573ce560'] = 'Aseta ALV-numerot mustalle listalle, jotta asiakas ei voi rekisteröityä joillakin näistä numeroista. Kirjoita yksi per yksi pilkulla erotettuna.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_7b13005d0082f3a02ff758d17debf5ad'] = 'Moduuli lisää tässä osiossa määritetyn tilan, kun asiakas tekee tilauksen. Jos tilauksen tila on voimassa oleva ALV-numero, tämä lisätään ensin ja heti sen jälkeen seuraava tila riippuen ostoprosessissa valituista maksutavoista. Jos tilauksen tila, jonka ALV-numero odottaa vahvistusta, koska API-prosessi epäonnistuu, se lisätään tilauksen viimeiseksi ja nykyiseksi tilaksi, jotta asiakas tietää, että hänen tilauksensa odottaa vahvistusta ALV-numerolla.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c2f6f7927f37822c3b597d3686a44e70'] = 'Tilauksen tila, kun ALV on vahvistettu';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5253f1fadf04ee3358f139e6040e1c80'] = 'Tämä vaihtoehto määrittää tilauksen tilan, kun ALV-numero on vahvistettu onnistuneesti. Tämä tila näytetään alussa, juuri ennen tilauksen oletustilaa. Poista vaihtoehto käytöstä valitsemalla [Disable]';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8a3ad48e7c2d0aa8fb38c2c03d13224a'] = 'Moduuli on luonut oman tilan nimeltä \"VAT-numero vahvistettu\". Mutta voit käyttää mitä tahansa mukautettua tilaa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f735ac75c9a297e148d80eff382ebe4b'] = 'Tilauksen tila, kun API-järjestelmä epäonnistuu';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d63a96b35bf6c72b9c138d0881421604'] = 'Tämä vaihtoehto määrittää tilauksen tilan, kun API-järjestelmä ei ole onnistunut vahvistamaan asiakkaan ALV-numeroa, kun [Skip validation] -vaihtoehto on aktivoitu ja asiakas on voinut jatkaa tilausta. Poista vaihtoehto käytöstä valitsemalla [Disable]';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_833f65cc3fe8b58eb450caf32d51f3a9'] = 'Moduuli on luonut oman tilan nimeltä \"VAT-numero odottaa vahvistusta\". Mutta voit käyttää mitä tahansa mukautettua tilaa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a81e07c3a2421768b9ee85c7c5e9df76'] = 'Asiakasryhmäjako maittain';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d850ba42b3ce90ace18bc59069f47c27'] = 'Järjestelmä jatkaa kaikkien asiakkaan luomien osoitteiden validointia niin kauan kuin ne täyttävät validoinnin ehdot, riippumatta siitä, onko osoitetyyppi valittu tässä osiossa esitetyssä vaihtoehdossa. Tämä vaihtoehto on vain sen määrittämiseksi, onko asiakas verovapaa valitessaan osoitetta kassaprosessissa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_66c36b9d18dd144a80435ebffd4b7ac1'] = 'ALV-vapautus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8cb88c12dc7c0a45a4e0bea3050bd233'] = 'Tämän vaihtoehdon avulla voit poistaa verot asiakkailta, joilla on voimassa oleva ALV-numero. Toimii kaikentyyppisissä validoinnissa (muoto tai API-järjestelmä).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_bd5bece1f53fae4660f7673d3f1f00bd'] = 'Tuotteiden hinnat ja ostoskorin määrät näytetään ilman veroja.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0f35945c0ec8ece14d52e5fb9fdb6572'] = 'Osoite tyyppi';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b85bee80d4cfb438d11cd19f63f7099f'] = 'Tämän vaihtoehdon avulla voit poistaa verot asiakkailta, joilla on voimassa oleva ALV-numero tietyssä osoitetyypissä (toimitusosoite, laskutusosoite tai molemmat).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_042d32665de5a16cbbe0aeb373948f60'] = 'Jos valitaan vaihtoehto \"laskuosoite ja toimitusosoite\", se on vapautettu verotuksesta, jos jommallakummalla tai molemmilla on voimassa oleva ALV-numero.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_601d8c4b9f72fc1862013c19b677a499'] = 'Laskutusosoite';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_af0f5bdc5be121b9307687aeeae38c17'] = 'Toimitusosoite';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ab330c76d81d3f96fb7d97d179c82bc7'] = 'Lasku ja toimitusosoite';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_09966285b248320d88be53355b466f21'] = 'Paikallinen maa';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_89a0979cda66d6e96fd0c7a12b9f8709'] = 'Tämän vaihtoehdon avulla voit määrittää paikallisen maan, jossa tuotteiden hinnat ja tilaukset verotetaan aina tässä maassa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_41699887750c4faa22a2103e0db81c20'] = 'Asiakasryhmien vapautus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b7d4d2cadf4db0aaab3bee7348154fd3'] = 'Tämän vaihtoehdon avulla voit poistaa verot tietyiltä asiakasryhmiltä, vaikka ALV-numero olisi voimassa tai ei. Jätä tyhjäksi, jos haluat poistaa sen käytöstä kaikilta asiakasryhmiltä. Jos valitset minkä tahansa ryhmän, verovapautus koskee vain valittujen ryhmien asiakkaita. Tämä vaihtoehto on täysin riippumaton [VAT exemption] -vaihtoehdosta.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0a365a829e2aecdb84fc372153aac60d'] = 'Laskun lakiteksti';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8b006b1a87879287f5c7c0a382857d01'] = 'Lisää lakiteksti laskuun arvonlisäverottomasta tilauksesta. Teksti lisätään alla oletusarvoiseen lakitekstiin.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_93f39badf1dd476bc3465e2366f91210'] = 'Laskun huomautus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_981bee80cb84e3422fe8e0de8d0694df'] = 'Lisää ALV-vapaan tilauksen laskuun huomautus. Teksti lisätään yllä lisättyihin muistiinpanoihin.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fe7fe004668ea7015c4ccc584dbafcca'] = 'Näitä vaihtoehtoja sovelletaan vain maihin, jotka on valittu tarkistettavaksi [Activation] -välilehdellä.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f028f32e19d6c84ce3238a20459f6d42'] = 'HUOMAA: Näitä vaihtoehtoja ei käytetä ALV-numeroiden vahvistamisessa Back-officesta.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_45c78c1b74b189ac8a5adc5b8e7a46c5'] = 'Vain ne kassamoduulit, jotka olemme integroineet 100 %:sti, ovat yhteensopivia tämän osion vaihtoehtojen kanssa. Jotkut näistä vaihtoehdoista eivät välttämättä toimi muiden kassamoduulien kanssa, edes niiden, joita tämä moduuli tukee ja jotka mainitaan yhteensopivuusluettelossa. Tämä johtuu siitä, että yleensä kassasivua hallitsevat moduulit käyttävät omia valintojaan ja ohjaimiaan moduulinsa kassaprosessissa näkyvien kenttien hallintaan.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_221094f1579a69ea1aed37744bc540f2'] = 'ALV-kenttä';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fc268a0f6d8150b1c6881adb0014e3c6'] = 'Valitse muuntaaksesi kentän valinnaiseksi tai pakolliseksi.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d6dc27fada47cb77f2dca329eacdbedc'] = 'Tämä vaihtoehto toimii vain validointiin valituissa maissa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e88e5e7b543453f0685b3b3593db4f9d'] = 'Valinnainen kenttä';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_19f823c6453c2b1ffd09cb715214813d'] = 'Vaadittu kenttä';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6b8c4fd358a49601a93e161d47a1b054'] = 'Näytä vain yritykselle';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5a777cce9211514bfadce87220ed49ab'] = 'Aktivoi tämä vaihtoehto näyttääksesi ALV-numerokentän vain, kun asiakkaat lisäävät yrityksen nimen. Piilota ALV-numerokenttä, kun yrityksen nimeä ei ole, ja vaikka valitset tämän kentän tarpeen mukaan, se muuttuu valinnaiseksi.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c0e292ad508997ec1c2a15d772cb128f'] = 'Tämä vaihtoehto toimii vain etutoimistossa. Yrityskenttä näytetään osoitemuodossa, mutta backofficessa joka tapauksessa.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b021df6aac4654c454f46c77646e745f'] = 'Label';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fbf1481544354c8de9e4f2fd5daff40d'] = 'Mukauta ALV-numerokentän tarra. Jätä tyhjäksi oletustunnisteeksi.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9b27e12d584b3438e811533b32e026e8'] = 'Legenda';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ad07132b12ffdc38b5d7ef9859d98e0b'] = 'Mukauta ALV-numerokentän selitystä. Se sijaitsee sisääntulon alapuolella. Jätä tyhjäksi oletustunnisteeksi.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f32f5ac2269b031043e213c23b4028eb'] = 'Summa %s on ALV-vapautuksen kynnys Yhdistyneen kuningaskunnan ALV-numeroissa. Valuuttakurssi tulee päivittää päivittäin CRON-tehtävän mukaan tai valuuttaosiossa.';
