$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9e2c3b66dc9c2c79111a8d11d9e9c332'] = 'Aktiiviset Brexit-verosäännöt vientiä varten Yhdistyneen kuningaskunnan maahan.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_469dc620989561ab9ca079454545bb1e'] = 'Alv-vapautus yrityksissä';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_53593000054652057f05c7ef687ba3e6'] = 'Tämä vaihtoehto sallii arvonlisäverovapautuksen yrityksille, joilla on voimassa oleva Ison-Britannian ALV-numero, kun ostoskorin tuotteiden kokonaismäärä on yhtä suuri tai pienempi kuin 135 GBP';
