$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ddeb8f4307f430983d53cb41b34474e1'] = 'Tämän vaihtoehdon avulla voit valita, ettet salli alle 135 GBP:n tai yli 135 GBP:n ostosten tekemistä.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8276092a35ba53068c987f7d7072809e'] = 'Yli 135 GBP';
