$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_25b74a3fe7cc70e18e584e84d87875fa'] = 'Sähköpostiosoitteet';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2b50033cc81272b6fb76594eaf7bdb0f'] = 'Voit asettaa eri sähköpostiosoitteita vastaanottamaan sähköposteja tästä moduulista. Sinun tulee kirjoittaa oikea sähköpostiosoite. Jos osoitteita on useita, kirjoita ne pilkuilla erotettuina (esim. testi@test.com,test2@test2.com...).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e2d81b28527e0dea0a247c058f5b2897'] = 'API-hälytyssähköposti';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e1e436bcf0f1584ab270e8d6e0662f55'] = 'Lähetä sähköposti-ilmoitus, kun asiakas on rekisteröitynyt ja API-järjestelmän ALV-vahvistus epäonnistuu.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_242263e7b06b99d29a69bc72407b9696'] = 'Lähetä sähköpostia asiakkaalle, kun API epäonnistuu';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ca58cd422878a1b1ae81aee7fb02fce'] = 'Lähetä asiakkaalle sähköpostiviesti, jossa ilmoitetaan, että tilauksen tila odottaa ALV-numeron vahvistamista, kun teet tilauksen osoitteella, jossa ALV-numeroa ei voitu vahvistaa API-järjestelmän vian vuoksi ja [Skip validation] -vaihtoehto on on aktivoitu vahvistusasetusten osiossa, jolloin asiakas voi jatkaa osoitteen ja tilauksen rekisteröintiä.';
