$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8e1d4cca72fb64311138e83a894aacd9'] = 'Lähetä sähköpostiviesti, kun asiakas on rekisteröitynyt ja ALV-vahvistus API-järjestelmän avulla on suoritettu onnistuneesti.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5be5f2a68a48c39d9c42b8a5fc2fbd17'] = 'CRON-asetukset ALV-numeroiden tarkistamiseen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b03b2f8739ada5eabe2ad2385370c659'] = 'Jatka tarkistusprosessia viimeisimmästä skannatusta osoitteesta';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_cd1a0229c38b3d47018619a1d1dddcc5'] = 'Tämä vaihtoehto on otettava käyttöön, jos haluat järjestelmän jatkavan skannausta viimeksi tarkistetusta osoitteesta. Tästä on hyötyä, kun viimeinen tarkistus epäonnistui tai jos et halua järjestelmän hakevan uudelleen ensimmäisestä tietokantaan tallennetusta osoitteesta.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f8e69246c2f0444c12a03bdf5ffa39bf'] = 'Tämä vaihtoehto ohittaa vahvistuksen, jos VIES/GOV.UK API -järjestelmä epäonnistuu vahvistusprosessin aikana. ALV-numero näkyy [Validated] ja järjestelmän tila punaisena muodossa [API request processing error] ALV-hallintaluettelossa.';
