$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_725c965b569cde8598c1a64b3ef35b73'] = 'Asiakas, jonka osoitteessa on voimassa oleva ALV-numero, liitetään valittuun ryhmään riippuen osoitemaasta. Jos asiakkaalla on useita osoitteita eri maista, järjestelmä lisää hänet niin moneen ryhmään kuin se on maittain määrittänyt.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_34c58cceb7dfc65149c483c400538067'] = 'Vaihtoehto [Use as default group] :';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_024eabed4f59a4927c8723fe0c914b70'] = 'Jos tämä vaihtoehto on käytössä, kun asiakas on määritetty ryhmään luodun osoitteen maan mukaan, tästä ryhmästä tulee tämän asiakkaan oletusryhmä. Jos asiakas lisää osoitteita eri maista, oletusryhmä vaihtuu siihen ryhmään, johon se lisättiin viimeksi.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_f600d68db7ba8913115bbd05608938ed'] = 'Vaihtoehto [Change default group with address] :';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_28d911ad25619fb5f1d88754dba47ebd'] = 'Jos tämä vaihtoehto on käytössä, kun asiakas valitsee tietyn osoitteen tilauksensa tekemistä varten kassaprosessissa, asiakkaan oletusryhmäksi vaihtuu ryhmä, joka kuuluu valitun osoitteen maahan.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_cc85ffddd57f9ec398514aef1ff9f298'] = 'Vaihtoehto [Remove customer from another groups] :';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_b6b4476becbf99ec2edffdb1d032898c'] = 'Jos tämä vaihtoehto on käytössä, asiakas liitetään luodun osoitteen maan valitsemaan ryhmään ja hänet poistetaan muista ryhmistä, joihin hän aiemmin kuului, ja se määritetään tähän ryhmään oletusryhmänä. Tämä vaihtoehto on hyödyllinen, kun haluat asiakkaan kuuluvan vain yhteen ryhmään, ei niin moneen kuin tiliisi on luotu osoitteita eri maista.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_205bb8060e975b0776bc4dac2a655092'] = 'Kun asiakas poistaa osoitteen tilistään, jos hänet on määrätty kyseiselle maalle määritettyyn ryhmään eikä hänellä ole enempää osoitteita samassa maassa, hänet poistetaan ryhmästä. Jos sillä olisi useampia osoitteita samassa maassa, se määritettäisiin silti kyseiseen ryhmään. Jos asiakas on liitetty vain osoitemaahansa kuuluvaan ryhmään ja hän poistaa osoitteen, järjestelmä poistaa hänet kyseisestä ryhmästä, jotta vältytään jäämästä ilman minkäänlaista ryhmää ja näin vältetään ristiriita tietokannan tiedoissa. , järjestelmä määrittää sen uudelleen ryhmään, joka on määritetty oletusarvoiseksi Prestashopissa rekisteröityneille asiakkaille.';
$_MODULE['<{advancedvatmanager}prestashop>faq_4ab310316fb4c1fe03d7dfdd06bf899d'] = 'Kun asiakas on jo tallentanut osoitteen, jossa on voimassa oleva ALV-numero, täytyykö hänen vahvistaa osoite aina tilauksen yhteydessä?';
$_MODULE['<{advancedvatmanager}prestashop>faq_6bc9f601d4bd8ba5c5bdc320ef13ef1d'] = 'Kun asiakas luo osoitteen, jolla on voimassa oleva ALV-numero, järjestelmä vahvistaa sen ja tallentaa vahvistustuloksen tietokantaan, joten aina kun hän käyttää samaa osoitetta tilausten tekemiseen, hänen ei tarvitse vahvistaa sitä uudelleen.';
$_MODULE['<{advancedvatmanager}prestashop>faq_d9c773e5a7c093f70c15421ce0649efe'] = 'Jos ALV-numeron vahvistus Cron -tehtävä suoritetaan ja kyseisen asiakkaan ALV-numero ei ole enää voimassa, järjestelmä havaitsee tämän ja asiakas ei ole enää arvonlisäverovapautettu ennen kuin hän lisää kelvollisen ALV-numeron uudelleen suunta.';
$_MODULE['<{advancedvatmanager}prestashop>faq_01b8106ef739e39e37ecd3b2aa59fbbf'] = 'Jos myymälässä on jo ennen moduulin asennusta tallennettuja asiakasosoitteita ALV-numeroineen, miten osoitteista voidaan tarkistaa, ovatko asiakkaat syöttäneet voimassa olevan ALV-numeron vai eivät?';
$_MODULE['<{advancedvatmanager}prestashop>faq_212d8a06c6b54e3da48e6012dc0a23ff'] = 'Moduulissa on CRON-tehtävätoiminto, joka tarkistaa kaikkien tietokantaan jo tallennettujen asiakasosoitteiden ALV-numerot. Kun moduuli on asennettu myymälään, järjestelmä tarkistaa automaattisesti niiden asiakkaiden ALV-numerot, jotka luovat osoitteen tai muokkaavat jo luomaansa.';
$_MODULE['<{advancedvatmanager}prestashop>faq_1a0ea82254a62da89cadd91ba343b23c'] = 'Aina kun suoritan CRON-tehtävän tarkistaakseni asiakkaiden ALV-numerot, tarkistaako prosessi kaikki tietokannan osoitteet uudelleen?';
$_MODULE['<{advancedvatmanager}prestashop>faq_7a2204718dfcecae6301eabebc53f85a'] = 'Järjestelmä tarkistaa kaikki tietokantaan tallennetut asiakasosoitteet, ellei \"Jatka tarkistusta viimeisestä skannatusta osoitteesta\" -vaihtoehtoa ole otettu käyttöön CRON-asetukset -osiossa.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_8137db6ff17c5e78f769e8d116c634fe'] = 'Jos Brexit-vaihtoehto on aktivoitu, järjestelmä laskee ostoskorin tuotteiden kokonaissumman ja jos se on yhtä suuri tai pienempi kuin %s (vastaa 135 GBP), verojen hallinta riippuu kustakin tilanteesta. Tämä vaihtoehto mahdollistaa Ison-Britannian ALV-numeroiden vahvistamisen GOV.UK-järjestelmän API:n avulla niin kauan kuin järjestelmän sovellusliittymän vahvistus on valittuna.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_5af404f31fadca9508383fc002a20fd6'] = 'Tämä järjestelmä on päivitetty uuteen Brexit-lakiin. Verovalvonta toimii seuraavasti:';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_0b83795dbb237b656e41ea8475c2d5f0'] = 'Ostoskorin summa 135 GBP tai vähemmän (ei sisällä toimituskuluja)';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_174aa92ed9957b09d0e9b6a273b1e54e'] = 'Yhdistyneessä kuningaskunnassa rekisteröidyt yritykset tai yksityishenkilöt, joilla ei ole ALV-numeroa:';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_7e7ad63a16be4e910a637232f5d7adf5'] = 'Tämä kauppa veloittaa Yhdistyneen kuningaskunnan maassa määritetyt verot.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_86dc36a261a4fa73344cf7ff30402bc1'] = 'Yritykset, joilla on Yhdistyneessä kuningaskunnassa rekisteröity ALV-numero:';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_016a392e7c93b7a65e77f8adbe3f3f37'] = 'Jos olet aktivoinut ALV-vapautus yrityksissä -vaihtoehdon, kauppa ei veloita veroja ja laskussa on viesti \"käänteinen verotus: asiakkaan tulee tilittää ALV HMRC:lle\". Jos vaihtoehto on poistettu käytöstä, se myös veloittaa veroja.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_47073281137dc85bd341888a68616f0c'] = 'Ostoskorin summa yli 135 GBP (ei sisällä toimituskuluja)';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_6a9414f4973ab35ac25ce88a92f007cf'] = 'Yhdistyneessä kuningaskunnassa rekisteröidyt yritykset tai yksityishenkilöt, joilla on tai ei ole ALV-numeroa:';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_fc817b43467d57cac1f70edc53e692e7'] = 'Tämä kauppa ei veloita veroja.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_08d59a447126862628e56d6bcd400c38'] = 'TÄRKEÄÄ: Tämän moduulin asennuksen aikana järjestelmä on luonut 232 Yhdistyneen kuningaskunnan osavaltiota (jos näitä ei ole luotu aiemmin) ja kohdistanut Pohjois-Irlannin Yhdistyneeseen kuningaskuntaan Brexit-lakien mukaisesti. Tämä parantaa asiakasosoitteiden luomista määrittämällä oikea provinssi tai osavaltio';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_1034384bb3e716cdcf48c7fd262b3b93'] = 'Asiakkaalla on osoite voimassa olevalla ALV-numerolla, mutta kauppa näyttää hinnat arvonlisäverollisina';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_ead42cb10374a80180e375cd97fb4314'] = 'Tarkista, ettei asiakas käytä toista osoitetta, joka on äskettäin luotu ja jota ei ole vahvistettu ostoprosessia varten.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_310686597cbfc21641b62b2020d07288'] = 'Tarkista, että ALV-vapautus-vaihtoehto on aktivoitu ALV-vapautusasetusten osiossa.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_92d98cd1576470905495f5efbccd96d2'] = 'Tarkista, että ALV-numero on vahvistettu oikein \"Asiakkaan ALV-numeron hallinta\" -osiossa.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_6bab09cd7d7b98611352ed0c5ec5adcd'] = 'Tarkista, että asiakas ei ole mukana asiakkaan ALV-vapautuksen hallintaosion luettelossa, kun \"arvonlisäveron pakkoperintä\" on valittuna.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_6ab787a221c015b92bac35153e152ae9'] = 'Tarkista, vastaako asiakkaan osoite Iso-Britanniaa ja täyttääkö arvonlisäveron perintäehdot.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_8f0f9049df637c0a87a8817d1ec87f9f'] = 'Tarkista, että asiakkaan oston tekemiseen käytettävä osoite vastaa ALV-vapautuksen määritysosiossa valittua \"Osoitteen tyyppi\" -vaihtoehtoa.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_c4b52015e73a1758b0f856ffb3675920'] = 'Tarkista, että sinulla ei ole asennettuna moduulia, joka ohjaa veroja ja on ristiriidassa Advanced VAT Manager -moduulin kanssa.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_058df4f029559cfd28ce27cc82a7fb4e'] = 'Kun asiakas tallentaa osoitteen, jossa on voimassa oleva ALV-numero ja on vapautettu arvonlisäverosta, tuotteiden hinnat näytetään ilman arvonlisäveroa, mutta pääsivun tuoteluettelon hinnat näkyvät edelleen arvonlisäverollisena.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_1d27f6d58f654c4bf9fa41911fe6132f'] = 'Tämä on sivuston välimuistin aiheuttama ongelma. Se tapahtuu useammin, jos sinulla on Prestashop-välimuisti käytössä ja [Never collect template files] -vaihtoehto smarty-osiossa. Ongelman ratkaisemiseksi Prestashopin välimuisti on puhdistettava. On suositeltavaa suorittaa Prestashop-välimuistin säännöllinen puhdistus CRON-tehtävillä.';
$_MODULE['<{advancedvatmanager}prestashop>configure_3f48c57b41a8fd83b522cb0beb195823'] = 'Advanced ALV Manager - Yleiskatsaus';
$_MODULE['<{advancedvatmanager}prestashop>configure_d1d2543752be06d0ab0fa3ddd4e71121'] = 'Tarkista myymälään rekisteröityneiden asiakkaiden ALV-numeroiden oikeellisuus. Hallinnoi asiakkaita, joilla on ALV-numero ja liitä heidät asiakasryhmiin automaattisesti. Poista verot tuotteiden hinnoista, hallitse Brexit-veropolitiikkaa ja monia muita vaihtoehtoja.';
$_MODULE['<{advancedvatmanager}prestashop>configure_b39bceeded94d6ced6100f53fa488e85'] = 'Tässä moduulissa on useita vaihtoehtoja ja lisäominaisuuksia. Sinun on luettava moduulin dokumentaatio huolellisesti ymmärtääksesi, miten se toimii yleisesti ja kunkin vaihtoehdon kanssa. Voit käyttää dokumentaatiota samalta määrityssivulta [Documentation] -välilehdeltä.';
