$_MODULE['<{advancedvatmanager}prestashop>information_5c33c6ca398955faf4749e5a44abf6b5'] = 'Tässä osiossa voit lisätä asiakkaita, joihin sovelletaan verovapautusta tai verovelvollisuutta riippumatta siitä, onko heillä osoite voimassa olevalla ALV-numerolla. Tämä luettelo on yhteensopiva usean myymälän tilan kanssa ja poikkeuksia voidaan myöntää asiakkaille kaikissa myymälöissä tai missä tahansa kaupassa.';
$_MODULE['<{advancedvatmanager}prestashop>information_1f744ebcd0206199d7fcca7159352f94'] = 'Tämä vaihtoehto on etusijalla muihin verovapautusvaihtoehtoihin nähden, jotka on määritetty moduulin määrityssivulla.';
$_MODULE['<{advancedvatmanager}prestashop>information_d9be54462f49a36c3fd70aeb8801f116'] = 'Kun asiakas lisätään listalle, hänelle myönnetään välittömästi joko arvonlisäverovapautus tai arvonlisäveron maksuvelvollisuus, riippuen \"alv-vaihtoehdossa\" valitusta vaihtoehdosta.';
$_MODULE['<{advancedvatmanager}prestashop>information_04bf2603a145f70ce793e34cd15f1e45'] = 'Tämä tarkoittaa, että valitusta vaihtoehdosta riippuen asiakas maksaa aina arvonlisäveron tai on vapautettu arvonlisäveron maksamisesta riippumatta muista ehdoista, jotka hän täyttää. Jos haluat asiakkaalle arvonlisäverovapautuksen moduulin vakioehtojen mukaisesti, sinun on poistettava se tästä luettelosta.';
