$_MODULE['<{advancedvatmanager}prestashop>form_539a9a6c4ffef3e54d1db703be6cf934'] = 'Yhteensopivuus/integrointi kolmannen osapuolen moduulien kanssa';
$_MODULE['<{advancedvatmanager}prestashop>form_3996658c333c79ad27594159e6075a34'] = 'Moduulimme on yhteensopiva useimpien moduulien kanssa. Se kuitenkin käyttää useita ohituksia, ja saman ohituksen samanaikainen käyttö voi aiheuttaa ristiriitaongelmia. Tässä tapauksessa sinun on otettava yhteyttä tekniseen tukipalveluumme, jotta voimme tarkistaa ja toteuttaa yhteensopivuuden.';
$_MODULE['<{advancedvatmanager}prestashop>form_660f83a666580bc14c6e247adf94bb9a'] = 'Prestashopin kassasivun hallintaan tarkoitetut moduulit voivat olla yhteensopimattomia moduulimme kanssa, koska nämä moduulit käyttävät omia ohjaimiaan kyseisen osion hallintaan. Tästä syystä suosittelemme käyttämään moduuliamme vain tässä yhteensopivuus- tai integraatioluettelossa olevien kassamoduulien kanssa.';
