$_MODULE['<{advancedvatmanager}prestashop>form_28371256b723459e31636eda1c651af6'] = 'HUOMAA: Niiden yhteensopivuus ei takaa, että jotkin moduulimme vaihtoehdot eivät toimi, kun jotkut näistä moduuleista aktivoidaan kaupassa. Yhteensopivuus varmistaa, että sekä asennetut että toimivat moduulit voivat toimia rinnakkain aiheuttamatta virheitä tai ristiriitoja niiden välillä. Vain täysin integroiduissa moduuleissa moduulimme toiminnot ja kaikki vaihtoehdot toimivat oikein ja integroituvat täydellisesti näihin moduuleihin. Suosittelemme hankkimaan ne moduulit, joihin olemme kehittäneet integraation ja jotka ovat integraatioluettelossa';
$_MODULE['<{advancedvatmanager}prestashop>form_e919d64d1fc38215cd5feb014694f1ab'] = 'YHTEENSOPIVUUSOHJEET';
$_MODULE['<{advancedvatmanager}prestashop>form_f5596427a7186c3c13aabdc64b7cacc5'] = 'Tämä moduuli on suunniteltu tekemään tarvittavat muutokset ohitustiedostoihin varmistaakseen yhteensopivuuden lueteltujen moduulien välillä, kun se on asennettu, käynnistetty uudelleen tai aktivoitu. Sinun ei tarvitse tehdä mitään, vaan koko prosessi tapahtuu automaattisesti. Kun moduulimme poistetaan käytöstä tai asennus poistetaan, moduulijärjestelmä palauttaa alkuperäisen koodin yhteensopivien moduulien ohituksista, jotka ovat tällä hetkellä aktivoituja.';
$_MODULE['<{advancedvatmanager}prestashop>form_16d06b3f6ba6c0f780a6a587987accf4'] = 'Jos sinulla on ongelmia ohitusmenetelmien koodin kanssa, jotka on mukautettu aiemmin. Aina kun se asennetaan tai aktivoidaan, moduuli tallentaa varmuuskopion kaikesta kaupan juurihakemiston [override] -kansion sisällöstä moduulihakemiston sisällä olevaan [backup] -kansioon.';
$_MODULE['<{advancedvatmanager}prestashop>form_74a1f4e0259f786597fbe6f48e45a20b'] = 'Asenna tai aktivoi jokin tässä yhteensopivuus- ja integraatioluettelossa mainittu moduuli';
$_MODULE['<{advancedvatmanager}prestashop>form_b94f6bb65017cec7bc1e733b8282f826'] = 'Jos sinulla on jo moduulimme asennettuna ja haluat asentaa jonkin tässä yhteensopivuus- ja integraatioluettelossa mainituista moduuleista, sinun tarvitsee vain deaktivoida moduulimme, asentaa haluamasi moduuli ja lopuksi aktivoida moduulimme uudelleen. Aktivoimalla moduulimme järjestelmä suorittaa yhteensopivuuden ohituksille.';
$_MODULE['<{advancedvatmanager}prestashop>form_794df3791a8c800841516007427a2aa3'] = 'Lisenssi';
$_MODULE['<{advancedvatmanager}prestashop>form_1fe917b01f9a3f87fa2d7d3b7643fac1'] = 'FAQ';
$_MODULE['<{advancedvatmanager}prestashop>form_0d445040963a32449561b1016c20cac2'] = 'Tästä osiosta löydät vastaukset joihinkin yleisimpiin kysymyksiin tai epäilyihin, jotka käyttäjien on selvennettävä ymmärtääkseen paremmin moduulin toiminnan.';
$_MODULE['<{advancedvatmanager}prestashop>form_231cf4c70d866b616c21baddaeed0696'] = 'Ongelmien karttoittaminen';
$_MODULE['<{advancedvatmanager}prestashop>form_6131a2d7732c63e42cbd9101cbd8d54d'] = 'Tästä osiosta löydät ratkaisun usein esiintyviin ongelmiin, joita voit löytää moduulin käytön aikana. Jos annetut ohjeet eivät ratkaise ongelmaa, suosittelemme, että otat yhteyttä tekniseen tukeemme, jotta voimme varmistaa ongelmasi.';
